// The update log (updates.ts) in every language: updates 49 to 51. See updates.ts in this folder.
import type { Row } from "./table.ts";

export const UPDATES10: Readonly<Record<string, Row>> = {
  "Belts, water barrels, a dressed follower, darker music, and capes made whole": ["ベルト、水樽、着飾った仲間、暗めの音楽、そして完全なマント", "허리띠, 물통, 차려입은 동행자, 더 어두운 음악, 그리고 온전해진 망토", "腰带、水桶、盛装的随从、更深沉的音乐，以及完整的披风", "腰帶、水桶、盛裝的隨從、更深沉的音樂，以及完整的披風", "Thắt lưng, thùng nước, người theo được diện đồ, nhạc trầm hơn, và áo choàng trọn vẹn", "Sabuk, tong air, pengikut berbusana, musik lebih gelap, dan jubah yang utuh", "เข็มขัด ถังน้ำ ผู้ติดตามที่แต่งตัว เพลงที่ทุ้มขึ้น และผ้าคลุมที่สมบูรณ์", "Kemerler, su fıçıları, giydirilmiş bir takipçi, daha koyu müzik ve bütünlenmiş pelerinler", "Cinturones, barriles de agua, un acompañante vestido, música más oscura y capas completas", "Cintos, barris de água, um seguidor vestido, música mais sombria e capas inteiras", "Пояса, бочки с водой, наряженный спутник, мрачнее музыка и цельные плащи", "Пояси, бочки з водою, вбраний супутник, похмуріша музика й цілісні плащі"],
  "A belt slot. The Apothecary's belt (Mother Yarrow, Mender Hale) holds 40 potions, 20 clean or ground herbs and 20 vials of water: brewing draws from it, and Sip (right-click it while worn) drinks a healing draught when you're hurt or the first potion otherwise. The Fletcher's belt (Hazel, Friendhollow's archery shop, Tallgrass) holds 500 shafts, 500 feathers, 500 headless arrows, 300 arrowheads and 50 bowstrings, and the knife reaches into it. Fill, Check and Empty like the other bags.": ["ベルト枠が追加。薬師のベルト（ヤロウおばさん、癒し手ヘイル）は薬40本、きれいにしたか潰した薬草20個、水の入った小瓶20本を収納：調合はここから取り出し、「すする」（身につけた状態で右クリック）で、けがをしていれば回復薬を、そうでなければ最初の薬を飲みます。矢職人のベルト（ヘイゼル、フレンドホロウの弓具店、トールグラス）は矢柄500、羽根500、矢じりなしの矢500、矢じり300、弓弦50を収納し、ナイフはそこから取り出します。ほかの袋と同じく「補充」「確認」「空にする」が使えます。", "허리띠 칸. 약사의 허리띠(야로 어머니, 치유사 헤일)는 물약 40개, 손질하거나 간 약초 20개, 물 약병 20개를 담습니다: 조제는 여기서 꺼내 쓰고, '한 모금'(착용 중 우클릭)은 다쳤을 땐 치유 물약을, 아니면 첫 물약을 마십니다. 화살장인의 허리띠(헤이즐, 프렌드할로우 활 가게, 톨그래스)는 화살대 500, 깃털 500, 촉 없는 화살 500, 화살촉 300, 활시위 50을 담고, 칼이 거기서 꺼내 씁니다. 다른 가방처럼 채우기, 확인, 비우기가 됩니다.", "新增腰带栏。药剂师腰带（亚罗大妈、治愈者黑尔）可装 40 瓶药水、20 份清理或研磨过的草药和 20 瓶水：调制时从中取用，啜饮（穿戴时右键）会在你受伤时喝治疗药剂，否则喝第一瓶药水。制箭匠腰带（黑兹尔、友谷的弓箭铺、高草原）可装 500 支箭杆、500 根羽毛、500 支无头箭、300 个箭头和 50 根弓弦，小刀会直接从中取用。和其他包一样可以装满、查看和清空。", "新增腰帶欄。藥劑師腰帶（亞羅大媽、治癒者黑爾）可裝 40 瓶藥水、20 份清理或研磨過的草藥和 20 瓶水：調製時從中取用，啜飲（穿戴時右鍵）會在你受傷時喝治療藥劑，否則喝第一瓶藥水。製箭匠腰帶（黑茲爾、友谷的弓箭鋪、高草原）可裝 500 支箭桿、500 根羽毛、500 支無頭箭、300 個箭頭和 50 根弓弦，小刀會直接從中取用。和其他包一樣可以裝滿、查看和清空。", "Ô thắt lưng. Thắt lưng nhà bào chế (Mẹ Yarrow, Thầy thuốc Hale) chứa 40 bình thuốc, 20 thảo dược đã làm sạch hoặc nghiền và 20 lọ nước: pha chế lấy từ đó, và Nhấp môi (nhấp chuột phải khi đang đeo) uống thuốc hồi máu khi bạn bị thương, không thì uống bình đầu tiên. Thắt lưng thợ làm tên (Hazel, tiệm cung Friendhollow, Tallgrass) chứa 500 thân tên, 500 lông, 500 mũi tên chưa đầu, 300 đầu mũi tên và 50 dây cung, và con dao lấy từ đó. Đổ đầy, Kiểm tra và Dọn trống như các túi khác.", "Slot sabuk. Sabuk peracik obat (Ibu Yarrow, Penyembuh Hale) menampung 40 ramuan, 20 herba bersih atau tergiling, dan 20 botol air: meracik mengambil darinya, dan Seruput (klik kanan saat dipakai) meminum ramuan penyembuh saat kau terluka atau ramuan pertama bila tidak. Sabuk pembuat panah (Hazel, toko panahan Friendhollow, Tallgrass) menampung 500 batang, 500 bulu, 500 panah tanpa mata, 300 mata panah, dan 50 tali busur, dan pisau mengambil darinya. Isi, Periksa, dan Kosongkan seperti tas lain.", "ช่องเข็มขัด เข็มขัดนักปรุงยา (แม่ยาร์โรว์ หมอเฮล) ใส่ยาได้ 40 ขวด สมุนไพรที่ทำความสะอาดหรือบดแล้ว 20 ชิ้น และขวดน้ำ 20 ขวด การปรุงยาดึงจากเข็มขัด และจิบ (คลิกขวาขณะสวม) จะดื่มยารักษาเมื่อคุณบาดเจ็บ ไม่อย่างนั้นดื่มขวดแรก เข็มขัดช่างทำลูกธนู (เฮเซล ร้านธนูเฟรนด์ฮอลโลว์ ทอลกราส) ใส่ก้านได้ 500 ขน 500 ลูกศรไม่มีหัว 500 หัวลูกศร 300 และสายธนู 50 และมีดหยิบจากในนั้นได้ เติม ตรวจ และเทออกได้เหมือนถุงอื่น", "Bir kemer yuvası. Eczacı kemeri (Yarrow Ana, Şifacı Hale) 40 iksir, 20 temiz ya da öğütülmüş ot ve 20 su şişesi alır: demleme oradan çeker ve Yudumla (giyiliyken sağ tıkla) yaralıysan bir iyileştirme iksiri, değilsen ilk iksiri içer. Okçu ustası kemeri (Hazel, Friendhollow'un okçu dükkânı, Tallgrass) 500 gövde, 500 tüy, 500 uçsuz ok, 300 ok ucu ve 50 yay kirişi alır ve bıçak içine uzanır. Diğer çantalar gibi Doldur, Kontrol Et ve Boşalt.", "Un hueco de cinturón. El Cinturón de boticario (Madre Yarrow, el sanador Hale) guarda 40 pociones, 20 hierbas limpias o molidas y 20 viales de agua: preparar saca de él, y Sorber (clic derecho con él puesto) bebe un brebaje curativo si estás herido o, si no, la primera poción. El Cinturón de flechero (Hazel, la tienda de arquería de Friendhollow, Tallgrass) guarda 500 astas, 500 plumas, 500 flechas sin punta, 300 puntas y 50 cuerdas de arco, y el cuchillo coge de él. Llenar, Revisar y Vaciar como las demás bolsas.", "Um espaço de cinto. O Cinto de boticário (Mãe Yarrow, curandeiro Hale) guarda 40 poções, 20 ervas limpas ou moídas e 20 frascos de água: o preparo puxa dele, e Bebericar (clique direito usando) bebe uma beberagem de cura quando você está ferido ou a primeira poção se não estiver. O Cinto de flecheiro (Hazel, a loja de arquearia de Friendhollow, Tallgrass) guarda 500 hastes, 500 penas, 500 flechas sem ponta, 300 pontas e 50 cordas de arco, e a faca pega de dentro dele. Encher, Conferir e Esvaziar como as outras bolsas.", "Слот пояса. Пояс аптекаря (Матушка Ярроу, целитель Хейл) вмещает 40 зелий, 20 очищенных или растёртых трав и 20 склянок воды: варка берёт из него, а «Отпить» (правый клик, когда надет) выпивает лечебный настой, если вы ранены, иначе — первое зелье. Пояс мастера стрел (Хейзел, лавка лучника во Френдхоллоу, Толлграсс) вмещает 500 древков, 500 перьев, 500 стрел без наконечников, 300 наконечников и 50 тетив, и нож достаёт из него. «Наполнить», «Проверить» и «Опустошить» — как у других сумок.", "Слот поясу. Пояс аптекаря (Матінка Ярроу, цілитель Гейл) вміщує 40 зіль, 20 очищених чи розтертих трав і 20 флаконів води: варіння бере з нього, а «Сьорбнути» (правий клік, коли надягнений) випиває лікувальний настій, якщо ви поранені, інакше — перше зілля. Пояс майстра стріл (Гейзел, лучна крамниця у Френдголлоу, Толлграс) вміщує 500 древок, 500 пір'їн, 500 стріл без наконечників, 300 наконечників і 50 тятив, і ніж дістає з нього. «Наповнити», «Перевірити» й «Спорожнити» — як в інших сумок."],
  "Water barrels in every village square fill all your empty vials for nothing, and every village store sells vials of water and empty vials.": ["どの村の広場にも水樽があり、空の小瓶をすべて無料で満たせます。村の店ではどこでも水の入った小瓶と空の小瓶を売っています。", "모든 마을 광장의 물통이 빈 약병을 모두 공짜로 채워 주고, 모든 마을 가게가 물 약병과 빈 약병을 팝니다.", "每个村庄广场的水桶都能免费装满你所有的空药瓶，每家村庄商店都卖装水的药瓶和空药瓶。", "每個村莊廣場的水桶都能免費裝滿你所有的空藥瓶，每家村莊商店都賣裝水的藥瓶和空藥瓶。", "Thùng nước ở mọi quảng trường làng đổ đầy mọi lọ rỗng của bạn miễn phí, và mọi cửa hàng làng bán lọ nước và lọ rỗng.", "Tong air di setiap alun-alun desa mengisi semua botol kosongmu gratis, dan setiap toko desa menjual botol air dan botol kosong.", "ถังน้ำที่ลานกลางทุกหมู่บ้านเติมขวดเปล่าทั้งหมดของคุณฟรี และร้านค้าทุกหมู่บ้านขายขวดน้ำและขวดเปล่า", "Her köy meydanındaki su fıçıları tüm boş şişelerini bedavaya doldurur ve her köy dükkânı su şişesi ve boş şişe satar.", "Los barriles de agua de cada plaza de pueblo llenan gratis todos tus viales vacíos, y todas las tiendas de pueblo venden viales de agua y viales vacíos.", "Barris de água em cada praça de vila enchem de graça todos os seus frascos vazios, e toda loja de vila vende frascos de água e frascos vazios.", "Бочки с водой на каждой деревенской площади бесплатно наполняют все ваши пустые склянки, а каждая деревенская лавка продаёт склянки с водой и пустые склянки.", "Бочки з водою на кожній сільській площі безкоштовно наповнюють усі ваші порожні флакони, а кожна сільська крамниця продає флакони з водою й порожні флакони."],
  "Your follower wears your wardrobe: on the Friends tab, dress the Friend following you in any piece you own (wings, halos, capes, hats, auras), one of each kind.": ["付き添う仲間があなたの衣装を着ます：フレンドタブで、あなたについてくるフレンドに手持ちのどの衣装でも着せられます（翼、光輪、マント、帽子、オーラ）。種類ごとに1つずつ。", "동행자가 당신의 옷장을 입습니다: 친구 탭에서 당신을 따르는 프렌드에게 가진 아이템 무엇이든 입힐 수 있습니다(날개, 후광, 망토, 모자, 오라). 종류마다 하나씩.", "你的随从会穿你的衣橱：在好友标签页中，为跟随你的伙伴穿上你拥有的任何物品（翅膀、光环、披风、帽子、光环特效），每种一件。", "你的隨從會穿你的衣櫥：在好友分頁中，為跟隨你的夥伴穿上你擁有的任何物品（翅膀、光環、披風、帽子、光環特效），每種一件。", "Người theo mặc tủ đồ của bạn: ở thẻ Bạn bè, mặc cho Bạn đang theo bạn bất kỳ món nào bạn sở hữu (cánh, hào quang, áo choàng, mũ, hào quang khí), mỗi loại một món.", "Pengikutmu memakai lemari pakaianmu: di tab Teman, dandani Sahabat yang mengikutimu dengan barang apa pun milikmu (sayap, lingkaran cahaya, jubah, topi, aura), satu dari tiap jenis.", "ผู้ติดตามใส่ตู้เสื้อผ้าของคุณ: ในแท็บเพื่อน แต่งตัวให้เพื่อนที่ติดตามคุณด้วยชิ้นใดก็ได้ที่คุณมี (ปีก วงรัศมี ผ้าคลุม หมวก ออร่า) ชนิดละหนึ่งชิ้น", "Takipçin senin gardırobunu giyiyor: Arkadaşlar sekmesinde seni takip eden Dostu sahip olduğun herhangi bir parçayla giydir (kanatlar, haleler, pelerinler, şapkalar, auralar), her türden bir tane.", "Tu acompañante viste tu vestuario: en la pestaña de Amigos, viste al Amigo que te sigue con cualquier pieza que tengas (alas, halos, capas, sombreros, auras), una de cada tipo.", "Seu seguidor veste seu guarda-roupa: na aba de Amigos, vista o Amigo que segue você com qualquer peça que você tenha (asas, auréolas, capas, chapéus, auras), uma de cada tipo.", "Спутник носит ваш гардероб: на вкладке «Друзья» оденьте следующего за вами Друга в любую вашу вещь (крылья, нимбы, плащи, шляпы, ауры), по одной каждого вида.", "Супутник носить ваш гардероб: на вкладці «Друзі» вдягніть Друга, що йде за вами, у будь-яку вашу річ (крила, німби, плащі, капелюхи, аури), по одній кожного виду."],
  "The music is darker: the bright modes bend to their minor cousins, tunes sit an octave lower, a drone hums under every section, the hall is deeper, and every band has a drummer now: a deep drum on every downbeat, kick and snare where the band is lively, low toms and a soft ride where it's calm.": ["音楽が暗めに：明るい旋法は短調寄りに、メロディは1オクターブ低く、どのパートの下にもドローンが鳴り、残響は深くなり、どのバンドにもドラマーが加わりました：強拍ごとに深い太鼓、賑やかなところではキックとスネア、穏やかなところでは低いタムとやわらかいライド。", "음악이 더 어두워졌습니다: 밝은 선법이 단조 쪽으로 기울고, 선율이 한 옥타브 낮아졌으며, 모든 구간 아래 드론이 울리고, 울림이 더 깊어졌으며, 모든 밴드에 드러머가 생겼습니다: 강박마다 깊은 북, 활기찬 곳엔 킥과 스네어, 잔잔한 곳엔 낮은 톰과 부드러운 라이드.", "音乐更深沉了：明亮的调式转向小调，旋律降低一个八度，每段下面都有持续低音，混响更深，每支乐队都有了鼓手：每个强拍一声低沉的鼓，热闹处有底鼓和军鼓，安静处有低音通鼓和轻柔的叮叮镲。", "音樂更深沉了：明亮的調式轉向小調，旋律降低一個八度，每段下面都有持續低音，混響更深，每支樂隊都有了鼓手：每個強拍一聲低沉的鼓，熱鬧處有大鼓和小鼓，安靜處有低音中鼓和輕柔的叮叮鈸。", "Âm nhạc trầm hơn: các điệu thức tươi sáng nghiêng về giọng thứ, giai điệu thấp hơn một quãng tám, một âm nền ngân dưới mỗi đoạn, không gian vang sâu hơn, và mỗi ban nhạc giờ có tay trống: trống trầm ở mỗi phách mạnh, trống bass và snare khi sôi động, tom trầm và ride nhẹ khi êm.", "Musiknya lebih gelap: modus cerah membelok ke sepupu minornya, melodi satu oktaf lebih rendah, dengung terdengar di bawah setiap bagian, ruangnya lebih dalam, dan setiap band kini punya penabuh drum: drum dalam di setiap ketukan berat, kick dan snare saat band bersemangat, tom rendah dan ride lembut saat tenang.", "ดนตรีทุ้มขึ้น: โหมดสดใสเอนไปทางไมเนอร์ ทำนองต่ำลงหนึ่งอ็อกเทฟ มีเสียงโดรนฮัมใต้ทุกท่อน ห้องก้องลึกขึ้น และทุกวงมีมือกลองแล้ว: กลองทุ้มทุกจังหวะหนัก กลองเบสกับสแนร์ตอนวงคึกคัก และทอมต่ำกับไรด์เบาๆ ตอนสงบ", "Müzik daha koyu: parlak modlar minör kuzenlerine kayıyor, melodiler bir oktav pes, her bölümün altında bir dron uğulduyor, salon daha derin ve her grubun artık bir davulcusu var: her vuruşta derin bir davul, grup hareketliyken bas davul ve trampet, sakinken pes tomlar ve yumuşak bir ride.", "La música es más oscura: los modos brillantes se inclinan a sus primos menores, las melodías bajan una octava, un bordón suena bajo cada sección, la sala es más profunda y cada banda tiene ahora batería: un tambor grave en cada tiempo fuerte, bombo y caja donde la banda está animada, toms graves y un ride suave donde está tranquila.", "A música está mais sombria: os modos brilhantes pendem para os primos menores, as melodias ficam uma oitava abaixo, um bordão soa sob cada seção, o salão é mais fundo e toda banda agora tem baterista: um tambor grave em cada tempo forte, bumbo e caixa onde a banda está animada, tons graves e um ride suave onde está calma.", "Музыка стала мрачнее: светлые лады склоняются к минорным, мелодии звучат на октаву ниже, под каждой частью гудит бурдон, зал глубже, и в каждом ансамбле теперь есть барабанщик: глухой барабан на каждую сильную долю, бочка и малый там, где оживлённо, низкие томы и мягкий райд там, где спокойно.", "Музика стала похмурішою: світлі лади схиляються до мінорних, мелодії звучать на октаву нижче, під кожною частиною гуде бурдон, зала глибша, і в кожному гурті тепер є барабанщик: глухий барабан на кожну сильну долю, бочка й малий там, де жваво, низькі томи й м'який райд там, де спокійно."],
  "Capes are full width again from the front and behind, so they show on both sides of a long Friend; from the side they follow the back and trail properly instead of boxing the body in.": ["マントは前後から見ると再び全幅になり、長いフレンドの両側に見えるように。横から見ると背中に沿って正しくたなびき、体を箱のように囲まなくなりました。", "망토가 앞뒤에서 다시 전체 너비가 되어, 긴 프렌드의 양쪽에 보입니다. 옆에서는 등을 따라 제대로 늘어지고, 몸을 상자처럼 가두지 않습니다.", "披风从正面和背面看又恢复全宽，在身形较长的伙伴两侧都能看到；从侧面看会顺着背部自然拖曳，而不是把身体框起来。", "披風從正面和背面看又恢復全寬，在身形較長的夥伴兩側都能看到；從側面看會順著背部自然拖曳，而不是把身體框起來。", "Áo choàng lại rộng hết cỡ khi nhìn từ trước và sau, nên hiện ở cả hai bên của một Bạn dài; nhìn từ bên, chúng theo lưng và buông xuống đúng cách thay vì đóng hộp quanh thân.", "Jubah kembali selebar penuh dari depan dan belakang, jadi tampak di kedua sisi Sahabat yang panjang; dari samping jubah mengikuti punggung dan menjuntai dengan benar alih-alih mengurung tubuh.", "ผ้าคลุมกว้างเต็มอีกครั้งเมื่อมองจากหน้าและหลัง จึงเห็นทั้งสองข้างของเพื่อนตัวยาว จากด้านข้างจะตามแนวหลังและพลิ้วลงอย่างถูกต้องแทนที่จะครอบตัวเป็นกล่อง", "Pelerinler önden ve arkadan yeniden tam genişlikte, böylece uzun bir Dostun iki yanında da görünüyor; yandan sırtı izleyip bedeni kutuya hapsetmek yerine düzgünce sarkıyor.", "Las capas vuelven a tener todo su ancho por delante y por detrás, así que se ven a ambos lados de un Amigo alargado; de lado siguen la espalda y caen como es debido en vez de encajonar el cuerpo.", "As capas voltam a ter a largura toda de frente e de trás, então aparecem dos dois lados de um Amigo comprido; de lado elas seguem as costas e caem direito em vez de encaixotar o corpo.", "Плащи снова во всю ширину спереди и сзади, так что видны с обеих сторон длинного Друга; сбоку они следуют за спиной и правильно спадают, а не заключают тело в коробку.", "Плащі знову на всю ширину спереду й ззаду, тож видно з обох боків довгого Друга; збоку вони йдуть за спиною й правильно спадають, а не замикають тіло в коробку."],
  "Parties and fellows, the Mage's Satchel, and a fuller fellowship wardrobe": ["パーティと仲間、Mage's Satchel、そして充実した団の衣装", "파티와 동료, Mage's Satchel, 그리고 더 풍성한 길드 옷장", "队伍与同伴、Mage's Satchel，以及更丰富的公会衣橱", "隊伍與同伴、Mage's Satchel，以及更豐富的公會衣櫥", "Tổ đội và đồng đội, Mage's Satchel, và tủ đồ bang hội phong phú hơn", "Party dan rekan, Mage's Satchel, dan lemari persekutuan yang lebih lengkap", "ปาร์ตี้และพวกพ้อง Mage's Satchel และตู้เสื้อผ้ากิลด์ที่ครบขึ้น", "Partiler ve dostlar, Mage's Satchel ve daha dolu bir kardeşlik gardırobu", "Grupos y compañeros, el Mage's Satchel y un vestuario de hermandad más completo", "Grupos e companheiros, o Mage's Satchel e um guarda-roupa de irmandade mais completo", "Группы и товарищи, Mage's Satchel и богаче гардероб братства", "Групи й товариші, Mage's Satchel і багатший гардероб братства"],
  "Parties: right-click any player (or press their name on the Friends tab) to invite them; they join from the banner. Party members within thirty tiles give you +10% XP, and \"/p\" in chat talks to the whole party privately. Fellows wearing your tag give +5% XP within twelve tiles with no party at all. Both stack with the friends-list bonus.": ["パーティ：どのプレイヤーでも右クリック（またはフレンドタブで名前を押す）で招待でき、相手はバナーから参加します。30マス以内のパーティメンバーで経験値+10%、チャットで「/p」と打つとパーティ全員に内緒で話せます。同じタグの仲間は、パーティを組まなくても12マス以内で経験値+5%。どちらもフレンドリストのボーナスと重複します。", "파티: 아무 플레이어나 우클릭(또는 친구 탭에서 이름 누르기)해 초대하면 배너에서 참가합니다. 30칸 안의 파티원은 경험치 +10%, 채팅에서 \"/p\"는 파티 전체와 비밀 대화. 같은 태그의 동료는 파티 없이도 12칸 안에서 경험치 +5%. 둘 다 친구 목록 보너스와 중첩됩니다.", "队伍：右键任意玩家（或在好友标签页按他们的名字）即可邀请；他们从横幅加入。三十格内的队友给你 +10% 经验，聊天中输入「/p」可私下和整个队伍说话。挂着你标签的同伴即使不组队，在十二格内也给 +5% 经验。两者都能和好友列表加成叠加。", "隊伍：右鍵任意玩家（或在好友分頁按他們的名字）即可邀請；他們從橫幅加入。三十格內的隊友給你 +10% 經驗，聊天中輸入「/p」可私下和整個隊伍說話。掛著你標籤的同伴即使不組隊，在十二格內也給 +5% 經驗。兩者都能和好友列表加成疊加。", "Tổ đội: nhấp chuột phải vào bất kỳ người chơi nào (hoặc nhấn tên họ ở thẻ Bạn bè) để mời; họ tham gia từ băng rôn. Thành viên tổ đội trong vòng ba mươi ô cho bạn +10% XP, và \"/p\" trong khung trò chuyện nói riêng với cả tổ đội. Đồng đội mang thẻ của bạn cho +5% XP trong vòng mười hai ô mà không cần tổ đội. Cả hai cộng dồn với thưởng danh sách bạn bè.", "Party: klik kanan pemain mana pun (atau tekan namanya di tab Teman) untuk mengundangnya; mereka bergabung dari spanduk. Anggota party dalam tiga puluh petak memberimu +10% XP, dan \"/p\" di obrolan berbicara secara pribadi ke seluruh party. Rekan yang memakai tagmu memberi +5% XP dalam dua belas petak tanpa party sama sekali. Keduanya bertumpuk dengan bonus daftar teman.", "ปาร์ตี้: คลิกขวาผู้เล่นคนใดก็ได้ (หรือกดชื่อในแท็บเพื่อน) เพื่อเชิญ พวกเขาเข้าร่วมจากแบนเนอร์ สมาชิกปาร์ตี้ในระยะสามสิบช่องให้ XP +10% และ \"/p\" ในแชทคุยกับทั้งปาร์ตี้แบบส่วนตัว พวกพ้องที่ใช้แท็กเดียวกันให้ XP +5% ในระยะสิบสองช่องโดยไม่ต้องตั้งปาร์ตี้ ทั้งสองซ้อนกับโบนัสรายชื่อเพื่อน", "Partiler: davet etmek için herhangi bir oyuncuya sağ tıkla (ya da Arkadaşlar sekmesinde adına bas); sancaktan katılırlar. Otuz kare içindeki parti üyeleri sana +%10 XP verir ve sohbette \"/p\" tüm partiyle özel konuşur. Etiketini taşıyan dostlar hiç parti olmadan on iki kare içinde +%5 XP verir. İkisi de arkadaş listesi bonusuyla birikir.", "Grupos: haz clic derecho en cualquier jugador (o pulsa su nombre en la pestaña de Amigos) para invitarlo; se une desde el aviso. Los miembros del grupo a menos de treinta casillas te dan +10 % de XP, y \"/p\" en el chat habla en privado con todo el grupo. Los compañeros con tu etiqueta dan +5 % de XP a menos de doce casillas sin necesidad de grupo. Ambos se suman al bonus de la lista de amigos.", "Grupos: clique direito em qualquer jogador (ou aperte o nome dele na aba de Amigos) para convidar; ele entra pela faixa. Membros do grupo a até trinta blocos dão +10% de XP, e \"/p\" no chat fala em particular com o grupo todo. Companheiros com sua tag dão +5% de XP a até doze blocos, sem grupo nenhum. Os dois somam com o bônus da lista de amigos.", "Группы: кликните правой кнопкой по любому игроку (или нажмите его имя на вкладке «Друзья»), чтобы пригласить; он вступает через баннер. Участники группы в пределах тридцати клеток дают +10% опыта, а «/p» в чате — приватный разговор со всей группой. Товарищи с вашей меткой дают +5% опыта в пределах двенадцати клеток вовсе без группы. Оба бонуса складываются с бонусом списка друзей.", "Групи: клацніть правою кнопкою по будь-якому гравцю (або натисніть його ім'я на вкладці «Друзі»), щоб запросити; він приєднується через банер. Учасники групи в межах тридцяти клітинок дають +10% досвіду, а «/p» у чаті — приватна розмова з усією групою. Товариші з вашою міткою дають +5% досвіду в межах дванадцяти клітинок зовсім без групи. Обидва бонуси складаються з бонусом списку друзів."],
  "The Mage's Satchel: a quest from Archmage Solenne at Magic 30 (3 leather, 60 star sigils, 20 thought sigils) for a purple bag with gold stars that holds 2,000 of every kind of sigil. Wear it on your back (Magic +3) or carry it; it catches the sigils you pick up, Fill puts your whole pack's sigils in, and every spell draws from it before your pockets.": ["Mage's Satchel：魔法30で受けられる大魔術師ソレンヌのクエスト（革3枚、星のシジル60、思念のシジル20）で、金の星がついた紫の袋が手に入り、どの種類のシジルも2,000個ずつ入ります。背負う（魔法+3）か持ち歩けば、拾ったシジルが入り、「補充」で荷物中のシジルを全部入れられ、どの呪文もポケットより先にここから使います。", "Mage's Satchel: 마법 30에 받는 대마법사 솔렌의 퀘스트(가죽 3, 별 인장 60, 사념 인장 20)로, 모든 종류의 인장을 2,000개씩 담는 금별 박힌 보라색 가방을 얻습니다. 등에 메거나(마법 +3) 들고 다니면 주운 인장을 받아 내고, 채우기로 가방의 인장을 모두 넣으며, 모든 주문이 주머니보다 먼저 여기서 꺼내 씁니다.", "Mage's Satchel：大法师索伦在魔法 30 级时给出的任务（3 块皮革、60 个星辰印记、20 个思绪印记），奖励一个缀着金星的紫色包，每种印记都能装 2,000 个。背在身后（魔法 +3）或随身携带；它会接住你捡到的印记，装满会把背包里所有印记放进去，每个法术都会先从它里面取用，再用口袋里的。", "Mage's Satchel：大法師索倫在魔法 30 級時給出的任務（3 塊皮革、60 個星辰印記、20 個思緒印記），獎勵一個綴著金星的紫色包，每種印記都能裝 2,000 個。背在身後（魔法 +3）或隨身攜帶；它會接住你撿到的印記，裝滿會把背包裡所有印記放進去，每個法術都會先從它裡面取用，再用口袋裡的。", "Mage's Satchel: nhiệm vụ từ Đại pháp sư Solenne ở Phép thuật 30 (3 da thuộc, 60 ấn sao, 20 ấn tư tưởng) để nhận một chiếc túi tím có sao vàng chứa 2.000 mỗi loại ấn. Đeo trên lưng (Phép thuật +3) hoặc mang theo; nó hứng ấn bạn nhặt, Đổ đầy cho hết ấn trong túi đồ vào, và mọi phép đều lấy từ nó trước túi áo của bạn.", "Mage's Satchel: misi dari Penyihir Agung Solenne di Sihir 30 (3 kulit, 60 sigil bintang, 20 sigil pikiran) untuk tas ungu berbintang emas yang menampung 2.000 setiap jenis sigil. Pakai di punggung (Sihir +3) atau bawa; ia menangkap sigil yang kau pungut, Isi memasukkan semua sigil di tasmu, dan setiap mantra mengambil darinya sebelum sakumu.", "Mage's Satchel: เควสต์จากมหาจอมเวทโซเลนน์ที่เวทมนตร์ 30 (หนัง 3 ผืน ผนึกดาว 60 ผนึกความคิด 20) ได้กระเป๋าสีม่วงประดับดาวทองที่ใส่ผนึกได้ชนิดละ 2,000 สะพายหลัง (เวทมนตร์ +3) หรือพกไว้ มันรับผนึกที่เก็บได้ เติมจะใส่ผนึกทั้งหมดในกระเป๋าลงไป และทุกคาถาดึงจากมันก่อนกระเป๋าเสื้อ", "Mage's Satchel: Büyü 30'da Başbüyücü Solenne'den bir görev (3 deri, 60 yıldız mührü, 20 düşünce mührü); her tür mühürden 2.000 alan altın yıldızlı mor bir çanta için. Sırtında (Büyü +3) ya da elinde taşı; topladığın mühürleri yakalar, Doldur çantandaki tüm mühürleri içine koyar ve her büyü ceplerinden önce ondan çeker.", "El Mage's Satchel: una misión de la archimaga Solenne con Magia 30 (3 de cuero, 60 sigilos de estrella, 20 sigilos de pensamiento) por una bolsa morada con estrellas doradas que guarda 2.000 de cada tipo de sigilo. Llévala a la espalda (Magia +3) o en la mochila; recoge los sigilos que tomas, Llenar mete todos los de tu mochila, y cada hechizo saca de ella antes que de tus bolsillos.", "O Mage's Satchel: uma missão da Arquimaga Solenne com Magia 30 (3 couros, 60 sigilos estelares, 20 sigilos de pensamento) por uma bolsa roxa com estrelas douradas que guarda 2.000 de cada tipo de sigilo. Use nas costas (Magia +3) ou carregue; ela pega os sigilos que você recolhe, Encher põe todos os sigilos da mochila nela, e todo feitiço puxa dela antes dos seus bolsos.", "Mage's Satchel: квест от Архимага Соленны на Магии 30 (3 кожи, 60 звёздных печатей, 20 печатей мысли) — фиолетовая сумка с золотыми звёздами, вмещающая по 2000 печатей каждого вида. Носите её на спине (Магия +3) или в сумке; она подхватывает подобранные печати, «Наполнить» складывает в неё все печати из сумки, и каждое заклинание берёт из неё раньше, чем из карманов.", "Mage's Satchel: квест від Архімагині Соленни на Магії 30 (3 шкіри, 60 зоряних печаток, 20 печаток думки) — фіолетова сумка із золотими зірками, що вміщує по 2000 печаток кожного виду. Носіть її на спині (Магія +3) або в сумці; вона підхоплює підібрані печатки, «Наповнити» складає в неї всі печатки із сумки, і кожне заклинання бере з неї раніше, ніж із кишень."],
  "Recruit on X from the fellowship menu: a card with your emblem, banner and colours, how many fellows you know of and how long the fellowship has stood, and a post whose link joins the fellowship (look and all) for 24 hours. Open the Realm by that link and it asks you in.": ["団のメニューから X で勧誘：紋章、旗、色、知っている仲間の数、団の結成からの期間が載ったカードと、24時間有効な団への参加リンク（見た目ごと）付きの投稿。そのリンクからレルムを開くと、参加を勧められます。", "길드 메뉴에서 X로 모집: 문장, 깃발, 색, 알고 있는 동료 수와 길드가 이어진 기간이 담긴 카드, 그리고 24시간 동안 길드(모습까지)에 가입시키는 링크가 담긴 게시물. 그 링크로 렐름을 열면 가입을 권합니다.", "从公会菜单在 X 上招募：一张印有你的徽章、旗帜和颜色、已知同伴人数以及公会成立时长的卡片，外加一条帖子，其链接在 24 小时内可加入公会（连同外观）。通过该链接打开王国，就会邀请你加入。", "從公會選單在 X 上招募：一張印有你的徽章、旗幟和顏色、已知同伴人數以及公會成立時長的卡片，外加一則貼文，其連結在 24 小時內可加入公會（連同外觀）。透過該連結打開王國，就會邀請你加入。", "Chiêu mộ trên X từ menu bang hội: một thẻ có huy hiệu, cờ và màu của bạn, số đồng đội bạn biết và bang hội đã tồn tại bao lâu, cùng một bài đăng có liên kết gia nhập bang hội (cả diện mạo) trong 24 giờ. Mở Vương quốc bằng liên kết đó và nó mời bạn vào.", "Rekrut di X dari menu persekutuan: kartu dengan lambang, spanduk, dan warnamu, berapa rekan yang kau tahu dan berapa lama persekutuan berdiri, dan postingan yang tautannya bergabung ke persekutuan (beserta tampilannya) selama 24 jam. Buka Realm lewat tautan itu dan ia mengajakmu masuk.", "รับสมัครบน X จากเมนูกิลด์: การ์ดที่มีตรา ธง และสีของคุณ จำนวนพวกพ้องที่คุณรู้จักและกิลด์ตั้งมานานเท่าไร และโพสต์ที่ลิงก์ใช้เข้าร่วมกิลด์ (รวมรูปลักษณ์) ได้ภายใน 24 ชั่วโมง เปิดอาณาจักรผ่านลิงก์นั้นแล้วมันจะชวนคุณเข้า", "Kardeşlik menüsünden X'te üye topla: amblemin, sancağın ve renklerin, tanıdığın dost sayısı ve kardeşliğin ne zamandır var olduğunu gösteren bir kart ve bağlantısı 24 saat boyunca kardeşliğe (görünüşüyle birlikte) katılan bir gönderi. Diyar'ı o bağlantıyla aç, seni içeri davet eder.", "Recluta en X desde el menú de la hermandad: una tarjeta con tu emblema, estandarte y colores, cuántos compañeros conoces y desde cuándo existe la hermandad, y una publicación cuyo enlace une a la hermandad (aspecto incluido) durante 24 horas. Abre el Reino con ese enlace y te invita a entrar.", "Recrute no X pelo menu da irmandade: um cartão com seu emblema, estandarte e cores, quantos companheiros você conhece e há quanto tempo a irmandade existe, e um post cujo link entra na irmandade (visual e tudo) por 24 horas. Abra o Reino por esse link e ele convida você a entrar.", "Набирайте в X из меню братства: карточка с вашей эмблемой, знаменем и цветами, числом известных вам товарищей и сроком существования братства, и пост, ссылка которого 24 часа принимает в братство (вместе с оформлением). Откройте Королевство по этой ссылке — и вас пригласят.", "Набирайте в X із меню братства: картка з вашою емблемою, знаменом і кольорами, кількістю відомих вам товаришів і часом існування братства, і допис, посилання якого 24 години приймає до братства (разом з оформленням). Відкрийте Королівство за цим посиланням — і вас запросять."],
  "Fellowship looks: sixteen more emblems (anchor, axe, hammer, heart, diamond, mountain, sun, key, tower, arrow, fish, rose, hourglass, lantern, paw, cup) and eight more banners (diagonal, quarters, border, dots, zigzag, sunburst, cross, fade). The adventurer card can put your fellowship's banner and emblem behind your Friend (Behind your Friend → Fellowship).": ["団の見た目：紋章が16種追加（錨、斧、ハンマー、ハート、ダイヤ、山、太陽、鍵、塔、矢、魚、バラ、砂時計、ランタン、肉球、杯）、旗が8種追加（斜め、四分割、縁取り、水玉、ジグザグ、放射、十字、グラデーション）。冒険者カードでは団の旗と紋章をフレンドの後ろに置けます（フレンドの後ろ → 団）。", "길드 모습: 문장 열여섯 추가(닻, 도끼, 망치, 하트, 다이아몬드, 산, 해, 열쇠, 탑, 화살, 물고기, 장미, 모래시계, 랜턴, 발바닥, 잔), 깃발 여덟 추가(대각선, 사분할, 테두리, 점, 지그재그, 햇살, 십자, 그러데이션). 모험가 카드는 길드 깃발과 문장을 프렌드 뒤에 둘 수 있습니다(프렌드 뒤 → 길드).", "公会外观：新增十六种徽章（锚、斧、锤、心、钻石、山、太阳、钥匙、塔、箭、鱼、玫瑰、沙漏、灯笼、爪印、杯）和八种旗帜（斜纹、四分、边框、圆点、锯齿、日芒、十字、渐变）。冒险者卡片可以把公会的旗帜和徽章放在伙伴身后（伙伴身后 → 公会）。", "公會外觀：新增十六種徽章（錨、斧、錘、心、鑽石、山、太陽、鑰匙、塔、箭、魚、玫瑰、沙漏、燈籠、爪印、杯）和八種旗幟（斜紋、四分、邊框、圓點、鋸齒、日芒、十字、漸層）。冒險者卡片可以把公會的旗幟和徽章放在夥伴身後（夥伴身後 → 公會）。", "Diện mạo bang hội: thêm mười sáu huy hiệu (mỏ neo, rìu, búa, trái tim, kim cương, núi, mặt trời, chìa khóa, tháp, mũi tên, cá, hoa hồng, đồng hồ cát, đèn lồng, dấu chân, chén) và thêm tám cờ (chéo, bốn ô, viền, chấm, zigzag, tia nắng, chữ thập, mờ dần). Thẻ nhà thám hiểm có thể đặt cờ và huy hiệu bang hội phía sau Bạn (Phía sau Bạn → Bang hội).", "Tampilan persekutuan: enam belas lambang lagi (jangkar, kapak, palu, hati, berlian, gunung, matahari, kunci, menara, panah, ikan, mawar, jam pasir, lentera, tapak, cawan) dan delapan spanduk lagi (diagonal, perempat, bingkai, titik, zig-zag, pancaran matahari, salib, pudar). Kartu petualang bisa menaruh spanduk dan lambang persekutuanmu di balik Sahabatmu (Di balik Sahabatmu → Persekutuan).", "รูปลักษณ์กิลด์: ตราเพิ่มอีกสิบหกแบบ (สมอ ขวาน ค้อน หัวใจ เพชร ภูเขา ดวงอาทิตย์ กุญแจ หอคอย ลูกศร ปลา กุหลาบ นาฬิกาทราย ตะเกียง รอยเท้า ถ้วย) และธงเพิ่มอีกแปดแบบ (เฉียง สี่ส่วน ขอบ จุด ซิกแซก รัศมีแดด กางเขน ไล่สี) บัตรนักผจญภัยวางธงและตรากิลด์ไว้ข้างหลังเพื่อนได้ (ข้างหลังเพื่อน → กิลด์)", "Kardeşlik görünüşleri: on altı amblem daha (çapa, balta, çekiç, kalp, elmas, dağ, güneş, anahtar, kule, ok, balık, gül, kum saati, fener, pati, kupa) ve sekiz sancak daha (çapraz, dörtlü, kenarlık, puantiye, zikzak, güneş ışını, haç, geçişli). Maceracı kartı kardeşliğinin sancağını ve amblemini Dostunun arkasına koyabiliyor (Dostunun arkası → Kardeşlik).", "Aspecto de hermandad: dieciséis emblemas más (ancla, hacha, martillo, corazón, diamante, montaña, sol, llave, torre, flecha, pez, rosa, reloj de arena, farol, huella, copa) y ocho estandartes más (diagonal, cuarteles, borde, lunares, zigzag, rayos de sol, cruz, degradado). La tarjeta de aventurero puede poner el estandarte y el emblema de tu hermandad detrás de tu Amigo (Detrás de tu Amigo → Hermandad).", "Visual de irmandade: mais dezesseis emblemas (âncora, machado, martelo, coração, diamante, montanha, sol, chave, torre, flecha, peixe, rosa, ampulheta, lanterna, pata, taça) e mais oito estandartes (diagonal, quartos, borda, bolinhas, zigue-zague, raios de sol, cruz, degradê). O cartão de aventureiro pode pôr o estandarte e o emblema da sua irmandade atrás do seu Amigo (Atrás do seu Amigo → Irmandade).", "Оформление братства: ещё шестнадцать эмблем (якорь, топор, молот, сердце, ромб, гора, солнце, ключ, башня, стрела, рыба, роза, песочные часы, фонарь, лапа, кубок) и ещё восемь знамён (диагональ, четверти, кайма, горошек, зигзаг, лучи солнца, крест, градиент). Карточка искателя приключений может поставить знамя и эмблему братства за Другом (За Другом → Братство).", "Оформлення братства: ще шістнадцять емблем (якір, сокира, молот, серце, ромб, гора, сонце, ключ, вежа, стріла, риба, троянда, пісковий годинник, ліхтар, лапа, кубок) і ще вісім знамен (діагональ, чверті, облямівка, горошок, зиґзаґ, промені сонця, хрест, градієнт). Картка шукача пригод може поставити знамено й емблему братства за Другом (За Другом → Братство)."],
  "A home of your own on Homestead Row, and capes that hang right": ["Homestead Row に自分の家を、そしてきちんと垂れるマント", "Homestead Row의 내 집, 그리고 제대로 늘어지는 망토", "在 Homestead Row 拥有自己的家，以及垂得正确的披风", "在 Homestead Row 擁有自己的家，以及垂得正確的披風", "Một ngôi nhà của riêng bạn ở Homestead Row, và áo choàng buông đúng cách", "Rumah milikmu sendiri di Homestead Row, dan jubah yang menjuntai dengan benar", "บ้านของคุณเองที่ Homestead Row และผ้าคลุมที่ห้อยได้ถูกต้อง", "Homestead Row'da kendi evin ve düzgün sarkan pelerinler", "Una casa propia en Homestead Row y capas que caen como deben", "Uma casa só sua na Homestead Row e capas que caem direito", "Свой дом на Homestead Row и плащи, что висят как надо", "Власний дім на Homestead Row і плащі, що висять як слід"],
  "Player housing: Steward Alder keeps the deed to a plot on Homestead Row, west of Friendhollow on the Westmarch road. A cottage costs 25,000 coins at Presence 15; it grows into a house (60,000, Presence 30) and a manor (150,000, Presence 50). Every Friend sees its own home there.": ["プレイヤーハウス：執事アルダーが、フレンドホロウの西、Westmarch への道沿いにある Homestead Row の区画の権利書を持っています。小屋は名声15で25,000コイン、家（60,000、名声30）、屋敷（150,000、名声50）へと大きくできます。どのフレンドにも、そこには自分の家が見えます。", "플레이어 하우스: 집사 올더가 프렌드할로우 서쪽 Westmarch 길가의 Homestead Row 부지 권리증을 갖고 있습니다. 오두막은 명성 15에 25,000코인이고, 집(60,000, 명성 30)과 저택(150,000, 명성 50)으로 키울 수 있습니다. 모든 프렌드가 거기서 자기 집을 봅니다.", "玩家住宅：管家奥尔德掌管着友谷以西、Westmarch 路边 Homestead Row 一块地的地契。小屋需要 25,000 金币和声望 15；可以扩建为房子（60,000，声望 30）和庄园（150,000，声望 50）。每个伙伴在那里看到的都是自己的家。", "玩家住宅：管家奧爾德掌管著友谷以西、Westmarch 路邊 Homestead Row 一塊地的地契。小屋需要 25,000 金幣和聲望 15；可以擴建為房子（60,000，聲望 30）和莊園（150,000，聲望 50）。每個夥伴在那裡看到的都是自己的家。", "Nhà ở người chơi: Quản gia Alder giữ giấy tờ một mảnh đất ở Homestead Row, phía tây Friendhollow trên đường Westmarch. Một căn nhà tranh giá 25.000 xu ở Danh tiếng 15; nó lớn thành một ngôi nhà (60.000, Danh tiếng 30) và một dinh thự (150.000, Danh tiếng 50). Mỗi Bạn thấy nhà của chính mình ở đó.", "Rumah pemain: Pengurus Alder memegang akta sebidang tanah di Homestead Row, di barat Friendhollow di jalan Westmarch. Pondok seharga 25.000 koin di Kehadiran 15; ia berkembang menjadi rumah (60.000, Kehadiran 30) dan rumah besar (150.000, Kehadiran 50). Setiap Sahabat melihat rumahnya sendiri di sana.", "บ้านผู้เล่น: พ่อบ้านอัลเดอร์ถือโฉนดที่ดินแปลงหนึ่งบน Homestead Row ทางตะวันตกของเฟรนด์ฮอลโลว์บนถนน Westmarch กระท่อมราคา 25,000 เหรียญที่ชื่อเสียง 15 ขยายเป็นบ้าน (60,000 ชื่อเสียง 30) และคฤหาสน์ (150,000 ชื่อเสียง 50) เพื่อนแต่ละตัวเห็นบ้านของตัวเองที่นั่น", "Oyuncu evleri: Kâhya Alder, Friendhollow'un batısında Westmarch yolundaki Homestead Row'da bir arsanın tapusunu tutuyor. Bir kulübe Şöhret 15'te 25.000 para; bir eve (60.000, Şöhret 30) ve bir konağa (150.000, Şöhret 50) büyüyor. Her Dost orada kendi evini görüyor.", "Viviendas de jugador: el mayordomo Alder guarda la escritura de una parcela en Homestead Row, al oeste de Friendhollow por el camino de Westmarch. Una casita cuesta 25.000 monedas con Presencia 15; crece a casa (60.000, Presencia 30) y a mansión (150.000, Presencia 50). Cada Amigo ve allí su propio hogar.", "Moradias de jogador: o Mordomo Alder guarda a escritura de um terreno na Homestead Row, a oeste de Friendhollow na estrada de Westmarch. Um chalé custa 25.000 moedas na Presença 15; vira casa (60.000, Presença 30) e mansão (150.000, Presença 50). Todo Amigo vê o próprio lar ali.", "Дома игроков: управитель Олдер хранит купчую на участок на Homestead Row к западу от Френдхоллоу на дороге Westmarch. Домик стоит 25 000 монет при Славе 15; он вырастает в дом (60 000, Слава 30) и в поместье (150 000, Слава 50). Каждый Друг видит там свой дом.", "Будинки гравців: управитель Олдер зберігає купчу на ділянку на Homestead Row на захід від Френдголлоу на дорозі Westmarch. Хатинка коштує 25 000 монет за Слави 15; вона виростає в дім (60 000, Слава 30) і в маєток (150 000, Слава 50). Кожен Друг бачить там свій дім."],
  "Furnish it with coins: a hearth to light, beds from a straw cot to a canopy bed (sleep in yours to wake with full health, faith and run energy and Well Rested, +5% to +10% XP for ten minutes), tables, seating, shelves, lamps, plants, a chest that becomes your bank at Presence 40, an armour stand and a statue of your Friend in a house, a house altar and a high seat in a manor.": ["コインで家具をそろえよう：火を灯す暖炉、わらの簡易寝台から天蓋付きベッドまで（自分のベッドで眠ると体力、信仰、走力が満タンで目覚め、Well Rested で10分間経験値+5%〜+10%）、テーブル、椅子、棚、ランプ、植物、名声40で銀行になる収納箱、家なら鎧立てとフレンドの像、屋敷なら家の祭壇と上座。", "코인으로 가구를 들이세요: 불을 지필 화로, 짚 침상부터 닫집 침대까지(내 침대에서 자면 체력, 신앙, 달리기 기력이 가득 찬 채 깨고, Well Rested로 10분간 경험치 +5%~+10%), 탁자, 의자, 선반, 등불, 화분, 명성 40에 은행이 되는 상자, 집에선 갑옷 받침대와 프렌드 석상, 저택에선 가정 제단과 상석.", "用金币布置家具：可以生火的壁炉，从草铺到四柱床的各种床（睡在自己的床上醒来时生命值、信仰和奔跑体力全满，并获得 Well Rested，十分钟内 +5% 到 +10% 经验），桌子、座椅、架子、灯、植物，一个在声望 40 时会变成你银行的箱子，房子里还有盔甲架和伙伴雕像，庄园里有家庭祭坛和高座。", "用金幣布置家具：可以生火的壁爐，從草鋪到四柱床的各種床（睡在自己的床上醒來時生命值、信仰和奔跑體力全滿，並獲得 Well Rested，十分鐘內 +5% 到 +10% 經驗），桌子、座椅、架子、燈、植物，一個在聲望 40 時會變成你銀行的箱子，房子裡還有盔甲架和夥伴雕像，莊園裡有家庭祭壇和高座。", "Trang bị nội thất bằng xu: lò sưởi để nhóm lửa, giường từ ổ rơm đến giường có màn (ngủ trên giường của mình để thức dậy đầy máu, đức tin và năng lượng chạy cùng Well Rested, +5% đến +10% XP trong mười phút), bàn, ghế, kệ, đèn, cây cảnh, một chiếc rương trở thành ngân hàng của bạn ở Danh tiếng 40, giá giáp và tượng Bạn của bạn trong một ngôi nhà, bàn thờ gia đình và ghế cao trong dinh thự.", "Lengkapi dengan koin: perapian untuk dinyalakan, ranjang dari dipan jerami hingga ranjang berkanopi (tidur di ranjangmu untuk bangun dengan nyawa, iman, dan energi lari penuh serta Well Rested, +5% hingga +10% XP selama sepuluh menit), meja, tempat duduk, rak, lampu, tanaman, peti yang menjadi bankmu di Kehadiran 40, rak zirah dan patung Sahabatmu di rumah, altar rumah dan kursi tinggi di rumah besar.", "ตกแต่งด้วยเหรียญ: เตาผิงให้จุดไฟ เตียงตั้งแต่แคร่ฟางถึงเตียงมีหลังคา (นอนบนเตียงของคุณเพื่อตื่นมาพร้อมพลังชีวิต ศรัทธา และพลังวิ่งเต็ม และได้ Well Rested XP +5% ถึง +10% เป็นเวลาสิบนาที) โต๊ะ ที่นั่ง ชั้นวาง ตะเกียง ต้นไม้ หีบที่กลายเป็นธนาคารของคุณที่ชื่อเสียง 40 ที่ตั้งเกราะและรูปปั้นเพื่อนในบ้าน และแท่นบูชาประจำบ้านกับที่นั่งสูงในคฤหาสน์", "Parayla döşe: yakılacak bir ocak, saman şilteden cibinlikli yatağa yataklar (kendi yatağında uyu, tam can, inanç ve koşu enerjisiyle ve Well Rested ile uyan, on dakika boyunca +%5 ile +%10 XP), masalar, oturaklar, raflar, lambalar, bitkiler, Şöhret 40'ta bankan olan bir sandık, bir evde zırh askısı ve Dostunun bir heykeli, bir konakta ev sunağı ve yüksek bir koltuk.", "Amuéblala con monedas: un hogar que encender, camas desde un catre de paja a una cama con dosel (duerme en la tuya para despertar con toda la vida, fe y energía de carrera y Well Rested, +5 % a +10 % de XP durante diez minutos), mesas, asientos, estantes, lámparas, plantas, un cofre que se convierte en tu banco con Presencia 40, un soporte de armadura y una estatua de tu Amigo en una casa, y un altar doméstico y un asiento de honor en una mansión.", "Mobilie com moedas: uma lareira para acender, camas de um catre de palha a uma cama com dossel (durma na sua para acordar com vida, fé e energia de corrida cheias e Well Rested, +5% a +10% de XP por dez minutos), mesas, assentos, prateleiras, lampiões, plantas, um baú que vira seu banco na Presença 40, um suporte de armadura e uma estátua do seu Amigo numa casa, e um altar doméstico e um assento de honra numa mansão.", "Обставьте за монеты: очаг, который можно разжечь, кровати от соломенной лежанки до кровати с балдахином (поспите в своей, чтобы проснуться с полным здоровьем, верой и энергией бега и Well Rested — +5–10% опыта на десять минут), столы, сиденья, полки, лампы, растения, сундук, который при Славе 40 становится вашим банком, стойка для доспехов и статуя Друга в доме, домашний алтарь и почётное кресло в поместье.", "Облаштуйте за монети: вогнище, яке можна розпалити, ліжка від солом'яного тапчана до ліжка з балдахіном (поспіть у своєму, щоб прокинутися з повним здоров'ям, вірою й енергією бігу та Well Rested — +5–10% досвіду на десять хвилин), столи, сидіння, полиці, лампи, рослини, скриня, що за Слави 40 стає вашим банком, стійка для обладунків і статуя Друга в домі, домашній вівтар і почесне крісло в маєтку."],
  "Decorate it with simulated RF, a Rare Casket each: half-timber, plank or stone walls; boards, flagstones, carpet or cobbles; six roofs; flower beds, hedges, lanterns or a family plot in the garden. Right-click the hearth (or ask the steward) to furnish and decorate.": ["シミュレーションのRFで飾ろう、各レアカスケット1つ：ハーフティンバー、板、石の壁、板張り、敷石、絨毯、石畳の床、6種の屋根、庭には花壇、生け垣、ランタン、家族の墓所。暖炉を右クリック（または執事に頼む）で家具と装飾を選べます。", "시뮬레이션 RF로 꾸미세요, 각각 희귀 상자 하나: 반목조, 판자, 돌 벽, 마루, 판석, 카펫, 자갈 바닥, 지붕 여섯 가지, 정원의 화단, 생울타리, 랜턴, 가족 묘역. 화로를 우클릭(또는 집사에게 부탁)해 가구와 장식을 고르세요.", "用模拟 RF 装饰，每项一个稀有宝匣：半木结构、木板或石墙；木地板、石板、地毯或鹅卵石；六种屋顶；花园里的花坛、树篱、灯笼或家族墓地。右键壁炉（或询问管家）来布置家具和装饰。", "用模擬 RF 裝飾，每項一個稀有寶匣：半木結構、木板或石牆；木地板、石板、地毯或鵝卵石；六種屋頂；花園裡的花壇、樹籬、燈籠或家族墓地。右鍵壁爐（或詢問管家）來布置家具和裝飾。", "Trang trí bằng RF mô phỏng, mỗi thứ một Rương hiếm: tường nửa gỗ, ván hoặc đá; sàn ván, đá phiến, thảm hoặc đá cuội; sáu kiểu mái; luống hoa, hàng rào cây, đèn lồng hoặc khu mộ gia đình trong vườn. Nhấp chuột phải vào lò sưởi (hoặc hỏi quản gia) để trang bị và trang trí.", "Hias dengan RF simulasi, masing-masing satu Peti Langka: dinding setengah kayu, papan, atau batu; lantai papan, ubin batu, karpet, atau batu bulat; enam atap; petak bunga, pagar tanaman, lentera, atau petak makam keluarga di taman. Klik kanan perapian (atau tanya pengurus) untuk melengkapi dan menghias.", "ตกแต่งด้วย RF จำลอง ชิ้นละหนึ่งหีบหายาก: ผนังครึ่งไม้ ไม้กระดาน หรือหิน พื้นไม้ แผ่นหิน พรม หรือหินกรวด หลังคาหกแบบ แปลงดอกไม้ รั้วต้นไม้ ตะเกียง หรือแปลงสุสานครอบครัวในสวน คลิกขวาเตาผิง (หรือถามพ่อบ้าน) เพื่อจัดเฟอร์นิเจอร์และตกแต่ง", "Simüle RF ile süsle, her biri bir Nadir Sandık: yarı ahşap, tahta ya da taş duvarlar; tahta, taş döşeme, halı ya da arnavut kaldırımı zemin; altı çatı; bahçede çiçek tarhları, çitler, fenerler ya da bir aile mezarlığı. Döşemek ve süslemek için ocağa sağ tıkla (ya da kâhyaya sor).", "Decórala con RF simulado, un Cofre raro cada cosa: paredes de entramado, tablones o piedra; suelos de tablas, losas, alfombra o adoquines; seis tejados; parterres, setos, faroles o una parcela familiar en el jardín. Haz clic derecho en el hogar (o pregunta al mayordomo) para amueblar y decorar.", "Decore com RF simulado, um Baú Raro cada: paredes de enxaimel, tábuas ou pedra; pisos de tábuas, lajes, carpete ou paralelepípedos; seis telhados; canteiros, cercas vivas, lanternas ou um jazigo de família no jardim. Clique direito na lareira (ou peça ao mordomo) para mobiliar e decorar.", "Украшайте за симулированный RF, по Редкой шкатулке за каждое: фахверковые, дощатые или каменные стены; полы из досок, плит, ковров или булыжника; шесть крыш; клумбы, живые изгороди, фонари или семейный участок в саду. Кликните правой кнопкой по очагу (или спросите управителя), чтобы обставлять и украшать.", "Прикрашайте за симульований RF, по Рідкісній скриньці за кожне: фахверкові, дощані чи кам'яні стіни; підлоги з дощок, плит, килимів чи бруківки; шість дахів; клумби, живоплоти, ліхтарі чи родинна ділянка в саду. Клацніть правою кнопкою по вогнищу (або спитайте управителя), щоб облаштовувати й прикрашати."],
  "Picture in picture: the ▣ on the minimap's ring (or Settings → Picture in picture) opens a floating window of the Realm that stays on top of other windows while you do something else; the game keeps running in the tab (view only: play in the tab). Browsers that can't do it say so.": ["ピクチャーインピクチャー：ミニマップの輪にある ▣（または 設定 → ピクチャーインピクチャー）で、ほかの作業中もほかのウィンドウの上に留まるレルムのフローティングウィンドウが開きます。ゲームはタブで動き続けます（表示のみ：操作はタブで）。対応していないブラウザではその旨が表示されます。", "PIP 모드: 미니맵 고리의 ▣(또는 설정 → PIP 모드)를 누르면 다른 일을 하는 동안 다른 창 위에 떠 있는 렐름 창이 열립니다. 게임은 탭에서 계속 돌아갑니다(보기 전용: 플레이는 탭에서). 지원하지 않는 브라우저는 그렇다고 알려 줍니다.", "画中画：小地图环上的 ▣（或 设置 → 画中画）会打开一个浮动的王国窗口，在你做别的事时始终置于其他窗口之上；游戏仍在标签页中运行（仅供观看：请在标签页中操作）。不支持的浏览器会提示。", "子母畫面：小地圖環上的 ▣（或 設定 → 子母畫面）會打開一個浮動的王國視窗，在你做別的事時始終置於其他視窗之上；遊戲仍在分頁中執行（僅供觀看：請在分頁中操作）。不支援的瀏覽器會提示。", "Hình trong hình: nút ▣ trên vòng bản đồ nhỏ (hoặc Cài đặt → Hình trong hình) mở một cửa sổ nổi của Vương quốc luôn ở trên các cửa sổ khác khi bạn làm việc khác; game vẫn chạy trong tab (chỉ xem: chơi trong tab). Trình duyệt không hỗ trợ sẽ báo.", "Gambar dalam gambar: ▣ di cincin peta mini (atau Pengaturan → Gambar dalam gambar) membuka jendela Realm mengambang yang tetap di atas jendela lain saat kau melakukan hal lain; game tetap berjalan di tab (hanya lihat: bermain di tab). Peramban yang tak mendukung akan memberi tahu.", "ภาพซ้อนภาพ: ▣ บนวงมินิแมป (หรือ ตั้งค่า → ภาพซ้อนภาพ) เปิดหน้าต่างลอยของอาณาจักรที่อยู่เหนือหน้าต่างอื่นขณะคุณทำอย่างอื่น เกมยังทำงานในแท็บ (ดูอย่างเดียว: เล่นในแท็บ) เบราว์เซอร์ที่ทำไม่ได้จะแจ้งให้ทราบ", "Resim içinde resim: mini harita halkasındaki ▣ (ya da Ayarlar → Resim içinde resim), sen başka bir şey yaparken diğer pencerelerin üstünde kalan yüzen bir Diyar penceresi açar; oyun sekmede çalışmaya devam eder (yalnızca izleme: sekmede oyna). Bunu yapamayan tarayıcılar söyler.", "Imagen en imagen: el ▣ del anillo del minimapa (o Ajustes → Imagen en imagen) abre una ventana flotante del Reino que se queda encima de las demás mientras haces otra cosa; el juego sigue funcionando en la pestaña (solo para mirar: se juega en la pestaña). Los navegadores que no pueden lo indican.", "Picture-in-picture: o ▣ no anel do minimapa (ou Configurações → Picture-in-picture) abre uma janela flutuante do Reino que fica por cima das outras enquanto você faz outra coisa; o jogo continua rodando na aba (só visualização: jogue na aba). Navegadores que não suportam avisam.", "Картинка в картинке: ▣ на кольце мини-карты (или Настройки → Картинка в картинке) открывает плавающее окно Королевства поверх других окон, пока вы заняты чем-то ещё; игра продолжает идти во вкладке (только просмотр: играйте во вкладке). Браузеры, которые так не умеют, об этом скажут.", "Картинка в картинці: ▣ на кільці мінімапи (або Налаштування → Картинка в картинці) відкриває плаваюче вікно Королівства поверх інших вікон, поки ви зайняті чимось іншим; гра триває у вкладці (лише перегляд: грайте у вкладці). Браузери, що так не вміють, про це скажуть."],
  "Whole sets in every armoury: any shop that sells a metal's helm and boots sells its cuirass, greaves, gauntlets and shield too (Frostpeak Outfitters' frostsilver and glimmer, the Highcairn forge's rarite, the Hollis Armoury's moonsilver, Emberforge Arms' ashsteel), and a shop with leather sells all of it.": ["どの防具屋でも一式がそろうように：ある金属の兜とブーツを売る店は、胸当て、すね当て、籠手、盾も売ります（フロストピーク装備店の frostsilver とグリマー、ハイケアン鍛冶場のレアライト、ホリス武具店のムーンシルバー、エンバーフォージ武器店のアッシュスチール）。革を扱う店は革装備をすべて売ります。", "모든 무기고에 한 벌 전체: 어떤 금속의 투구와 장화를 파는 가게는 흉갑, 정강이받이, 건틀릿, 방패도 팝니다(프로스트피크 장비점의 frostsilver와 글리머, 하이케언 대장간의 레어라이트, 홀리스 무구점의 월은, 엠버포지 무기점의 잿빛강철). 가죽을 파는 가게는 가죽 장비를 모두 팝니다.", "每家军械铺都有全套：卖某种金属头盔和靴子的商店，也会卖它的胸甲、护胫、护手和盾牌（霜峰装备铺的 frostsilver 和微光、高冢铁匠铺的稀晶、霍利斯军械铺的月银、烬炉兵器铺的灰钢），卖皮革的商店也会卖全套皮甲。", "每家軍械鋪都有全套：賣某種金屬頭盔和靴子的商店，也會賣它的胸甲、護脛、護手和盾牌（霜峰裝備鋪的 frostsilver 和微光、高塚鐵匠鋪的稀晶、霍利斯軍械鋪的月銀、燼爐兵器鋪的灰鋼），賣皮革的商店也會賣全套皮甲。", "Trọn bộ ở mọi kho vũ khí: cửa hàng nào bán mũ giáp và ủng của một kim loại cũng bán giáp ngực, giáp chân, găng giáp và khiên của nó (frostsilver và ánh kim ở Đồ dã ngoại Frostpeak, rarit ở Lò rèn Highcairn, bạc trăng ở Kho vũ khí Hollis, thép tro ở Vũ khí Emberforge), và cửa hàng có đồ da bán đủ cả bộ.", "Set lengkap di setiap toko zirah: toko mana pun yang menjual helm dan sepatu bot suatu logam juga menjual zirah dada, pelindung kaki, sarung tangan zirah, dan perisainya (frostsilver dan kemilau di Perlengkapan Frostpeak, rarit di Tempa Highcairn, perak bulan di Gudang Senjata Hollis, baja abu di Senjata Emberforge), dan toko yang menjual kulit menjual semuanya.", "ครบชุดในทุกร้านเกราะ: ร้านไหนขายหมวกเกราะและรองเท้าบูตของโลหะใด ก็ขายเกราะอก สนับแข้ง ถุงมือเกราะ และโล่ของโลหะนั้นด้วย (frostsilver และประกายแสงที่ร้านอุปกรณ์ฟรอสต์พีก แรไรต์ที่โรงตีเหล็กไฮแคร์น เงินจันทร์ที่คลังอาวุธฮอลลิส เหล็กเถ้าที่ร้านอาวุธเอมเบอร์ฟอร์จ) และร้านที่มีหนังก็ขายครบทุกชิ้น", "Her zırhçıda tam takımlar: bir metalin miğferini ve botlarını satan her dükkân göğüslüğünü, dizliklerini, eldivenlerini ve kalkanını da satıyor (Frostpeak Donanım'ın frostsilver ve parıltısı, Highcairn Demirhanesi'nin raritı, Hollis Cephaneliği'nin ay gümüşü, Emberforge Silahları'nın kül çeliği) ve deri satan bir dükkân hepsini satıyor.", "Conjuntos completos en cada armería: toda tienda que vende el yelmo y las botas de un metal vende también su coraza, grebas, guanteletes y escudo (el frostsilver y el destello de Equipos de Frostpeak, la rarita de la Forja de Highcairn, la plata lunar de la Armería Hollis, el acero ceniza de Armas de Emberforge), y una tienda con cuero lo vende todo.", "Conjuntos completos em todo arsenal: qualquer loja que vende o elmo e as botas de um metal vende também a couraça, as grevas, as manoplas e o escudo (o frostsilver e o lampejo de Equipamentos de Frostpeak, a rarita da Forja de Highcairn, a prata lunar do Arsenal Hollis, o aço cinzento de Armas de Emberforge), e uma loja com couro vende tudo.", "Полные комплекты в каждой оружейной: любая лавка, продающая шлем и сапоги из металла, продаёт и его кирасу, поножи, латные перчатки и щит (frostsilver и мерцалит в «Снаряжении Фростпика», рарит в Кузнице Хайкэрна, лунное серебро в Оружейной Холлиса, пепельная сталь в «Оружии Эмберфорджа»), а лавка с кожей продаёт её всю.", "Повні комплекти в кожній зброярні: будь-яка крамниця, що продає шолом і чоботи з металу, продає і його кірасу, наголінники, латні рукавиці й щит (frostsilver і мерехтит у «Спорядженні Фростпіку», рарит у Кузні Гайкерна, місячне срібло в Зброярні Голліса, попеляста сталь у «Зброї Емберфорджа»), а крамниця зі шкірою продає її всю."],
  "The time-of-day badge and the players-online count sit under the minimap now, clear of the ring's buttons.": ["時刻のバッジとオンライン人数がミニマップの下に移り、輪のボタンと重ならなくなりました。", "시간대 배지와 접속자 수가 이제 미니맵 아래에 있어 고리의 버튼과 겹치지 않습니다.", "时间标记和在线玩家数现在位于小地图下方，不再挡住环上的按钮。", "時間標記和在線玩家數現在位於小地圖下方，不再擋住環上的按鈕。", "Huy hiệu giờ trong ngày và số người chơi online giờ nằm dưới bản đồ nhỏ, không che các nút trên vòng.", "Lencana waktu dan jumlah pemain online kini di bawah peta mini, tak menghalangi tombol di cincinnya.", "ป้ายเวลาของวันและจำนวนผู้เล่นออนไลน์ตอนนี้อยู่ใต้มินิแมป ไม่บังปุ่มบนวง", "Günün saati rozeti ve çevrimiçi oyuncu sayısı artık mini haritanın altında, halkanın düğmelerinden uzakta.", "La insignia de la hora del día y el contador de jugadores conectados están ahora bajo el minimapa, lejos de los botones del anillo.", "O selo da hora do dia e a contagem de jogadores online agora ficam sob o minimapa, longe dos botões do anel.", "Значок времени суток и счётчик игроков в сети теперь под мини-картой, подальше от кнопок кольца.", "Значок пори доби й лічильник гравців у мережі тепер під мінімапою, подалі від кнопок кільця."],
  "Full screen: the ↗ on the minimap's ring (or Settings → Full screen) fills your screen with the Realm; press it again, or Esc, to come back.": ["全画面：ミニマップの輪にある ↗（または 設定 → 全画面）で画面いっぱいにレルムを表示。もう一度押すか Esc で戻ります。", "전체 화면: 미니맵 고리의 ↗(또는 설정 → 전체 화면)로 화면을 렐름으로 가득 채웁니다. 다시 누르거나 Esc로 돌아옵니다.", "全屏：小地图环上的 ↗（或 设置 → 全屏）让王国铺满整个屏幕；再按一次或按 Esc 即可退出。", "全螢幕：小地圖環上的 ↗（或 設定 → 全螢幕）讓王國鋪滿整個螢幕；再按一次或按 Esc 即可退出。", "Toàn màn hình: nút ↗ trên vòng bản đồ nhỏ (hoặc Cài đặt → Toàn màn hình) cho Vương quốc phủ kín màn hình; nhấn lại hoặc Esc để quay về.", "Layar penuh: ↗ di cincin peta mini (atau Pengaturan → Layar penuh) memenuhi layarmu dengan Realm; tekan lagi, atau Esc, untuk kembali.", "เต็มจอ: ↗ บนวงมินิแมป (หรือ ตั้งค่า → เต็มจอ) ทำให้อาณาจักรเต็มหน้าจอ กดอีกครั้งหรือ Esc เพื่อกลับ", "Tam ekran: mini harita halkasındaki ↗ (ya da Ayarlar → Tam ekran) ekranını Diyar'la doldurur; geri dönmek için yeniden bas ya da Esc.", "Pantalla completa: el ↗ del anillo del minimapa (o Ajustes → Pantalla completa) llena tu pantalla con el Reino; vuelve a pulsarlo, o Esc, para volver.", "Tela cheia: o ↗ no anel do minimapa (ou Configurações → Tela cheia) enche sua tela com o Reino; aperte de novo, ou Esc, para voltar.", "Полный экран: ↗ на кольце мини-карты (или Настройки → Полный экран) разворачивает Королевство на весь экран; нажмите снова или Esc, чтобы вернуться.", "Повний екран: ↗ на кільці мінімапи (або Налаштування → Повний екран) розгортає Королівство на весь екран; натисніть знову або Esc, щоб повернутися."],
  "Capes hang properly on long Friends: seen from the side the cape follows the back of the body and trails behind instead of boxing in the whole figure; from behind and in front the hem flares from the shoulders, not the widest part.": ["長いフレンドにもマントがきちんと垂れるように：横から見ると体全体を囲むのではなく背中に沿って後ろへたなびき、前後から見ると裾は一番幅の広いところではなく肩から広がります。", "긴 프렌드에게도 망토가 제대로 늘어집니다: 옆에서 보면 몸 전체를 가두지 않고 등을 따라 뒤로 늘어지고, 앞뒤에서 보면 밑단이 가장 넓은 부분이 아니라 어깨에서 퍼집니다.", "身形较长的伙伴披风也垂得自然了：从侧面看，披风顺着背部向后拖曳，而不是把整个身形框住；从背面和正面看，下摆从肩部展开，而不是从最宽处。", "身形較長的夥伴披風也垂得自然了：從側面看，披風順著背部向後拖曳，而不是把整個身形框住；從背面和正面看，下襬從肩部展開，而不是從最寬處。", "Áo choàng buông đúng cách trên Bạn dài: nhìn từ bên, áo choàng theo lưng và kéo dài phía sau thay vì đóng hộp cả thân; từ sau và trước, gấu áo xòe từ vai, không phải từ chỗ rộng nhất.", "Jubah menjuntai dengan benar pada Sahabat yang panjang: dari samping jubah mengikuti punggung dan menjuntai ke belakang alih-alih mengurung seluruh sosok; dari belakang dan depan kelimnya mengembang dari bahu, bukan dari bagian terlebar.", "ผ้าคลุมห้อยถูกต้องบนเพื่อนตัวยาว: มองจากด้านข้างผ้าคลุมตามแนวหลังและพลิ้วไปข้างหลังแทนที่จะครอบทั้งตัว จากด้านหลังและด้านหน้าชายผ้าบานออกจากไหล่ ไม่ใช่จากส่วนที่กว้างที่สุด", "Pelerinler uzun Dostlarda düzgün sarkıyor: yandan bakınca pelerin tüm bedeni kutuya hapsetmek yerine sırtı izleyip arkadan sarkıyor; arkadan ve önden etek en geniş yerden değil omuzlardan açılıyor.", "Las capas caen como deben en Amigos alargados: de lado la capa sigue la espalda y cae detrás en vez de encajonar toda la figura; por detrás y por delante el bajo se abre desde los hombros, no desde la parte más ancha.", "As capas caem direito em Amigos compridos: de lado a capa segue as costas e cai para trás em vez de encaixotar a figura toda; de trás e de frente a barra se abre a partir dos ombros, não da parte mais larga.", "Плащи правильно висят на длинных Друзьях: сбоку плащ следует за спиной и спадает назад, а не заключает всю фигуру в коробку; сзади и спереди подол расходится от плеч, а не от самой широкой части.", "Плащі правильно висять на довгих Друзях: збоку плащ іде за спиною й спадає назад, а не замикає всю постать у коробку; ззаду й спереду поділ розходиться від плечей, а не від найширшої частини."],
};
